const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const regionName = 'Sakha'; // Region name for filtering FAO/GAUL
    const countryName = 'Russian Federation'; // Country name for FAO/GAUL
    const date = '2020-08-06';
    const startDate = ee.Date(date);
    const endDate = startDate.advance(1, 'day'); // One day period

    // Get Sakha Republic geometry from FAO/GAUL/2015/level1
    const gaul = ee.FeatureCollection('FAO/GAUL/2015/level1');
    const sakha = gaul.filter(
      ee.Filter.and(
        ee.Filter.eq('ADM0_NAME', countryName),
        ee.Filter.eq('ADM1_NAME', 'Sakha (Yakutiya) Republic')
      )
    ).first();

    if (!sakha) {
      console.log("Error: Sakha Republic geometry not found.");
      console.log("C3"); // Calculation failure due to missing geometry
      return;
    }
    const geometry = sakha.geometry();

    // 2. Data Acquisition
    // Using MODIS Thermal Anomalies/Fire_5 (MCD14ML)
    let fireCollection = ee.ImageCollection('MODIS/051/MCD14ML')
      .filterDate(startDate, endDate)
      .filterBounds(geometry);

    const initialSize = await fireCollection.size().getInfo();
    if (initialSize === 0) {
      console.log(`No MODIS fire images found for ${date}.`);
      console.log("C1");
      return;
    }
    console.log(`Images found for ${date}: ${initialSize}`);

    // Select the 'fire' band and count pixels with fire confidence >= 7 (low, nominal, or high confidence)
    // The 'fire' band contains processed values:
    // 7 = Low confidence fire
    // 8 = Nominal confidence fire
    // 9 = High confidence fire
    // Other values indicate non-fire or processing issues.
    const firesDetected = fireCollection.select('fire').map(function(image) {
      // Create a binary image where 1 indicates a fire and 0 indicates no fire.
      return image.gte(7).rename('active_fire').copyProperties(image, ['system:time_start']);
    });

    // If there are multiple images for the day (e.g., Terra and Aqua passes), mosaic them.
    // Use an OR reducer to combine binary fire detections: if any sensor detected fire, it's a fire.
    const dailyFireImage = firesDetected.mosaic();

    // Ensure dailyFireImage is not null/empty after mosaic
    if (!dailyFireImage) {
      console.log("C3"); // Mosaicing failed or resulted in null
      return;
    }

    // 3. Processing and Calculation
    // Calculate the total number of active fire pixels.
    // Scale for MODIS fire pixels is 1000m. Using 1000m scale for reduction.
    const fireCountResult = await dailyFireImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 1000, // MODIS pixel size
      maxPixels: 1e9,
    }).get('active_fire').getInfo();

    // 4. Validation & Final Answer
    if (fireCountResult === null || isNaN(fireCountResult)) {
      console.log("Calculation of active fire pixels failed (result is null/NaN).");
      console.log("C3");
      return;
    }

    // Ensure we have valid pixels in the region for reduction
    // We can't directly check reduceRegion pixel count without a separate reducer.
    // If sum is 0, it means no fires. If fireCountResult is null, it's C3.
    // If the image itself was completely masked out after processing, this sum would be 0, which is a valid "no fires" scenario.
    // So, C2 logic for valid pixel count is less relevant here if `fireCountResult` is 0, which means 0 active_fire pixels.

    const activeFireCount = fireCountResult;
    console.log(`Active fires detected in Sakha Republic on ${date}: ${activeFireCount}`);

    if (activeFireCount > 8) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.log(`An error occurred: ${error.message}`);
    // Check for common error types
    if (error.message.includes('ImageCollection.mosaic: Collection must have images.')) {
        console.log("C1"); // No images to mosaic
    } else if (error.message.includes('Invalid argument specified for ee.Date()')) {
        console.log("D"); // Date format error
    } else if (error.message.includes('is not a function') || error.message.includes('has no such band')) {
        console.log("D"); // Method or band name error
    } else {
        console.log("C3"); // Generic calculation failure
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
